create table security.engagements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid not null references app.projects(id) on delete cascade,created_by uuid not null references auth.users(id),name text not null check(char_length(name) between 1 and 160),type security.engagement_type not null,status text not null default 'draft' check(status in ('draft','ready','active','paused','completed','cancelled')),starts_at timestamptz,ends_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint engagement_window_valid check(ends_at is null or starts_at is null or ends_at>starts_at)); create index engagements_project_status_idx on security.engagements(project_id,status);
create table security.authorization_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid not null references app.projects(id) on delete cascade,engagement_id uuid references security.engagements(id) on delete cascade,status security.authorization_status not null default 'draft',valid_from timestamptz,valid_until timestamptz,authorization_evidence_file_id uuid,uploaded_by uuid references auth.users(id),reviewed_by uuid references auth.users(id),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint authorization_window_valid check(valid_until is null or valid_from is null or valid_until>valid_from)); create index authorization_engagement_status_idx on security.authorization_records(engagement_id,status,valid_until);
create table security.engagement_scope(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid not null references app.projects(id) on delete cascade,engagement_id uuid not null references security.engagements(id) on delete cascade,type security.scope_type not null,value text not null check(char_length(value) between 1 and 2048),normalized_value text not null check(char_length(normalized_value) between 1 and 2048),is_excluded boolean not null default false,metadata jsonb not null default '{}'::jsonb,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(engagement_id,type,normalized_value,is_excluded)); create index scope_engagement_lookup_idx on security.engagement_scope(engagement_id,type,normalized_value);
create table security.findings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid not null references app.projects(id) on delete cascade,engagement_id uuid references security.engagements(id) on delete set null,created_by uuid references auth.users(id),source_agent_run_id uuid,title text not null check(char_length(title) between 1 and 240),summary text,description text,severity security.severity not null default 'informational',confidence numeric(5,2) check(confidence between 0 and 100),status security.finding_status not null default 'potential',affected_asset text,category text,impact text,recommendation text,first_observed_at timestamptz,validated_at timestamptz,resolved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz); create index findings_project_severity_status_idx on security.findings(project_id,severity,status) where deleted_at is null;
create table artifacts.files(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid references app.projects(id) on delete cascade,uploaded_by uuid not null references auth.users(id),storage_bucket text not null default 'project-artifacts',storage_path text not null,original_name text not null,declared_mime_type text,detected_mime_type text,size_bytes bigint not null check(size_bytes>=0),content_hash text,source text not null default 'upload',status artifacts.file_status not null default 'quarantined',processing_version text,parser_version text,blocked_reason text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(storage_bucket,storage_path)); create index files_project_status_idx on artifacts.files(project_id,status,created_at desc) where deleted_at is null; create index files_org_created_idx on artifacts.files(organization_id,created_at desc) where deleted_at is null;
alter table security.authorization_records add constraint authorization_records_evidence_file_fk foreign key(authorization_evidence_file_id) references artifacts.files(id) on delete set null;
create table artifacts.file_versions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,file_id uuid not null references artifacts.files(id) on delete cascade,version integer not null check(version>0),storage_path text not null,content_hash text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(file_id,version));
create table artifacts.file_chunks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organizations(id) on delete cascade,project_id uuid references app.projects(id) on delete cascade,file_id uuid not null references artifacts.files(id) on delete cascade,chunk_index integer not null check(chunk_index>=0),content text not null,content_hash text not null,embedding extensions.vector,embedding_model_version_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(file_id,chunk_index,content_hash)); create index file_chunks_project_file_idx on artifacts.file_chunks(organization_id,project_id,file_id,chunk_index);
